package br.com.admeclesial.interfaces.web.relatorio;
import br.com.admeclesial.application.relatorio.*; import br.com.admeclesial.domain.financeiro.StatusContaAPagar; import br.com.admeclesial.infrastructure.persistence.financeiro.FornecedorRepository; import org.springframework.format.annotation.DateTimeFormat; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import java.time.LocalDate; import java.util.UUID;
@Controller @RequestMapping("/relatorios/contas-a-pagar") public class RelatorioContaPagarWebController { private final RelatorioContaPagarApplicationService service; private final RelatorioContextoService contexto; private final FornecedorRepository fornecedores; public RelatorioContaPagarWebController(RelatorioContaPagarApplicationService s,RelatorioContextoService c,FornecedorRepository f){service=s;contexto=c;fornecedores=f;}
 @GetMapping public String tela(@RequestParam(required=false) UUID organizacaoUuid,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate vencimentoInicio,@RequestParam(required=false) @DateTimeFormat(iso=DateTimeFormat.ISO.DATE) LocalDate vencimentoFim,@RequestParam(required=false) UUID fornecedorUuid,@RequestParam(required=false) StatusContaAPagar status,@RequestParam(defaultValue="false") boolean somenteVencidas,@RequestParam(defaultValue="0") int pagina,@RequestParam(defaultValue="25") int tamanho,Model m){m.addAttribute("organizacoes",contexto.organizacoesAutorizadas());m.addAttribute("fornecedores",fornecedores.findAllByOrderByNomeAsc());m.addAttribute("statusOpcoes",StatusContaAPagar.values());m.addAttribute("organizacaoUuid",organizacaoUuid);m.addAttribute("vencimentoInicio",vencimentoInicio);m.addAttribute("vencimentoFim",vencimentoFim);m.addAttribute("fornecedorUuid",fornecedorUuid);m.addAttribute("status",status);m.addAttribute("somenteVencidas",somenteVencidas);if(organizacaoUuid!=null){var f=new RelatorioContaPagarFiltro(organizacaoUuid,vencimentoInicio,vencimentoFim,fornecedorUuid,status,somenteVencidas,pagina,tamanho);m.addAttribute("resultado",service.pesquisar(f));m.addAttribute("resumo",service.resumo(f));}return "relatorio/contas-a-pagar";}
}
